import{_ as a,o as r,c as t,a3 as o}from"./chunks/framework.DDcl5AtZ.js";const h=JSON.parse('{"title":"Kubernetes Namespace Factory","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),s={name:"index.md"};function n(i,e,c,d,l,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="kubernetes-namespace-factory" tabindex="-1">Kubernetes Namespace Factory <a class="header-anchor" href="#kubernetes-namespace-factory" aria-label="Permalink to &quot;Kubernetes Namespace Factory&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Kubernetes Namespace Factory is an Ansible project for declaratively creating, updating, and removing namespaces and a selected set of namespace-scoped resources. The inventory identifies the namespaces to manage; each inventory host has a matching file under <code>host_vars/</code>.</p><p>The <code>apply.yml</code> playbook applies the roles in a controlled order. Namespace configuration and optional resources are defined as YAML variables, with shared defaults in <code>group_vars/all.yml</code>. Changes are reviewed through GitHub pull requests before an authorized operator applies them to a cluster.</p><h2 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h2><ul><li><a href="./customer/ordering-namespace.html">Users</a>: request or decommission a namespace.</li><li><a href="./maintainer/ci-cd-secrets-setup.html">Repository maintainers</a>: maintain CI, schemas, and docs.</li><li><a href="./provisioner/operating-services.html">Kubernetes provisioners and providers</a>: review requests and maintain required cluster APIs and controllers.</li><li><a href="./versioning.html">Versioning</a>: understand releases and documentation versions.</li></ul><p>The navigation version selector lets you switch between the latest published documentation and available tagged releases.</p><h2 id="supported-resources" tabindex="-1">Supported resources <a class="header-anchor" href="#supported-resources" aria-label="Permalink to &quot;Supported resources&quot;">​</a></h2><p>The playbook manages namespaces, resource quotas and limit ranges, External Secrets, ConfigMaps, Gateway API HTTPRoutes, and ExternalDNS DNSEndpoints. Some resources require their corresponding CRDs, operators, or provider configuration to be installed in the target cluster. See the <a href="./provisioner/operating-services.html">provisioner guide</a> before requesting them.</p>',9)])])}const m=a(s,[["render",n]]);export{h as __pageData,m as default};
